        "description": "지난해 매출 96억원으로 역대 최대 실적을 냈으며, 올해 5월 153억원 규모의시리즈B투자를유치해 누적투자액 220억원을 확보했다. 새 성장 축은 기업의 AX를 소셜 데이터로 이끄는 것이다. 장 대표는 \"대부분의 기업이 방대한 소셜 데이터를 담당자별로 흩어진 파일로 관리해 자산으로 활용하지 못하고 있다...새 창 열림",
