        "description": "인터넷에서 미국의 한 스타트업이 식물성 섬유로 동물성 모피와 시어링을 대체하는 소재를 개발해 LVMH 이노베이션 어워드를 계기로투자 유치에... 현재시리즈A투자를 준비하는 이유도 여기에 있다. 소재 성능은 이미 검증됐고, 이제 관건은 양산이다. 자동차나 신발처럼 대량 공급이 필요한 시장에...새 창 열림",
